// src/services/newsService.ts
import axios from 'axios';

const API_KEYS = {
  newsapi: process.env.REACT_APP_NEWSAPI_KEY,
  nytimes: process.env.REACT_APP_NYTIMES_KEY,
  guardian: process.env.REACT_APP_GUARDIAN_KEY,
};

const fetchNews = async (query: string, source: string) => {
  let url = '';

  switch (source) {
    case 'newsapi':
      url = `https://newsapi.org/v2/everything?q=${query}&apiKey=${API_KEYS.newsapi}`;
      break;
    case 'nytimes':
      url = `https://api.nytimes.com/svc/search/v2/articlesearch.json?q=${query}&api-key=${API_KEYS.nytimes}`;
      break;
    case 'guardian':
      url = `https://content.guardianapis.com/search?q=${query}&api-key=${API_KEYS.guardian}&show-fields=headline,byline,body,publishedDate`;
      break;
  }

  const response = await axios.get(url);
  return normalizeResponse(response.data, source);
};

// ✅ Normalize API responses into a common format
const normalizeResponse = (data: any, source: string) => {
  switch (source) {
    case 'newsapi':
      return data.articles.map((article: any) => ({
        title: article.title,
        description: article.description,
        url: article.url,
        author: article.author || 'Unknown',
        publishedAt: article.publishedAt,
      }));

    case 'nytimes':
      return data.response.docs.map((article: any) => ({
        title: article.headline.main,
        description: article.abstract,
        url: article.web_url,
        author: article.byline?.original || 'Unknown',
        publishedAt: article.pub_date,
      }));

    case 'guardian':
      return data.response.results.map((article: any) => ({
        title: article.fields.headline,
        description: article.fields.body.substring(0, 200) + '...',
        url: article.webUrl,
        author: article.fields.byline || 'Unknown',
        publishedAt: article.fields.publishedDate,
      }));

    default:
      return [];
  }
};

export { fetchNews };
